import { test, expect, type APIRequestContext } from '@playwright/test';

const PNG_32X32 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAKklEQVR4nGP4Yh9HU8QwasGoBaMWjFowasGoBaMWjFowasGoBaMWDBULAN4gRFtH0KHXAAAAAElFTkSuQmCC',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

test.describe.serial('通知接入、主流导航栏、Instagram双栏详情与WebSocket实时推送盲测套件', () => {
  test('1. 宽屏左侧导航栏改版、居中紧凑间距几何审计与通知入口验证', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const healthRes = await page.request.get('/api/health');
    expect(healthRes.status()).toBe(200);
    expect((await healthRes.json()).ok).toBe(true);

    const nick = `宽屏体验官${Date.now().toString().slice(-4)}`;
    await loginUser(page.request, makeEmail('layout-nav'), nick);

    await page.goto('/');
    await expect(page.locator('body')).toBeVisible();
    // 守护隐藏管理路由：公开社区禁止任何 /admin 链接
    await expect(page.locator('a[href="/admin"]')).toHaveCount(0);
    await expect(page.locator('a[href="/admin/"]')).toHaveCount(0);

    const sidebar = page.locator('aside').first();
    const mainArea = page.locator('main').first();
    await expect(sidebar).toBeVisible({ timeout: 10000 });
    await expect(mainArea).toBeVisible({ timeout: 10000 });

    const sidebarBox = await sidebar.boundingBox();
    const mainBox = await mainArea.boundingBox();
    expect(sidebarBox, '左侧导航栏应具备可见几何尺寸').not.toBeNull();
    expect(mainBox, '主内容区应具备可见几何尺寸').not.toBeNull();
    if (sidebarBox && mainBox) {
      expect(sidebarBox.x).toBeLessThan(mainBox.x);
      const horizontalGap = mainBox.x - (sidebarBox.x + sidebarBox.width);
      expect(horizontalGap, '左侧导航栏与中心动态区应紧邻不重叠').toBeGreaterThanOrEqual(-12);
      expect(horizontalGap, '1440px宽屏下左侧导航栏与主内容区间距应紧凑自然(<=140px)').toBeLessThanOrEqual(140);
    }

    // 验证主导航包含 动态、通知、私信、主页 四项入口
    const feedNav = sidebar
      .getByRole('button', { name: /动态/ })
      .or(sidebar.getByRole('link', { name: /动态/ }))
      .first();
    const notifNav = sidebar
      .getByRole('button', { name: /通知/ })
      .or(sidebar.getByRole('link', { name: /通知/ }))
      .first();
    const dmNav = sidebar
      .getByRole('button', { name: /私信/ })
      .or(sidebar.getByRole('link', { name: /私信/ }))
      .first();
    const homeNav = sidebar
      .getByRole('button', { name: /主页/ })
      .or(sidebar.getByRole('link', { name: /主页/ }))
      .first();

    await expect(feedNav).toBeVisible();
    await expect(notifNav).toBeVisible();
    await expect(dmNav).toBeVisible();
    await expect(homeNav).toBeVisible();

    await notifNav.click();
    await expect(mainArea).toBeVisible();
    await feedNav.click();
    expect(pageErrors, '导航改版与切换过程不应存在前端未捕获异常').toEqual([]);
  });

  test('2. 通知模块全链路 API 契约、防自发、参数边界、跨用户隔离与删帖清理', async ({ page, browser }) => {
    const ctxB = await browser.newContext();
    const ctxC = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录访问通知与汇总未读接口必须返回 401
      expect((await anonCtx.request.get('/api/notifications')).status()).toBe(401);
      expect((await anonCtx.request.get('/api/notifications/unread-count')).status()).toBe(401);
      expect((await anonCtx.request.post('/api/notifications/read', { data: { all: true } })).status()).toBe(401);

      const userA = await loginUser(page.request, makeEmail('notif-a'), '创作者小光');
      const userB = await loginUser(ctxB.request, makeEmail('notif-b'), '互动好友小雨');
      await loginUser(ctxC.request, makeEmail('notif-c'), '无关旁观者小风');

      // 非法参数与空请求体边界校验
      expect((await page.request.get('/api/notifications?type=invalid')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?limit=100')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?offset=-1')).status()).toBe(400);
      expect((await page.request.post('/api/notifications/read', { data: {} })).status()).toBe(400);
      expect((await page.request.post('/api/notifications/read', { data: { ids: [] } })).status()).toBe(400);

      // 用户 A 发布一篇帖子，并对自己帖子点赞和评论 -> 不应产生任何自发通知
      const postTitle = `通知校验图文-${Date.now()}`;
      const postRes = await page.request.post('/api/posts', {
        data: { title: postTitle, content: '测试评论、点赞与关注通知闭环' },
      });
      expect(postRes.status()).toBe(201);
      const postId = (await postRes.json()).post.id;

      expect((await page.request.post(`/api/posts/${postId}/like`)).status()).toBe(200);
      expect(
        (await page.request.post(`/api/posts/${postId}/comments`, { data: { content: '作者自评' } })).status()
      ).toBe(201);

      const selfNotifJson = await (await page.request.get('/api/notifications')).json();
      expect(selfNotifJson.unreadCount, '本人点赞与评论自身帖子不得生成自发通知').toBe(0);
      expect(selfNotifJson.notifications.length).toBe(0);

      // 用户 B 对用户 A 执行：关注、点赞、评论
      expect((await ctxB.request.post(`/api/users/${userA.id}/follow`)).status()).toBe(200);
      expect((await ctxB.request.post(`/api/posts/${postId}/like`)).status()).toBe(200);
      const bComment = `来自好友的精彩评论-${Date.now()}`;
      const bCommentRes = await ctxB.request.post(`/api/posts/${postId}/comments`, {
        data: { content: bComment },
      });
      expect(bCommentRes.status()).toBe(201);

      // 验证全部通知列表包含 comment、like、follow 三类且未读数 >= 3
      const allNotifRes = await page.request.get('/api/notifications?type=all');
      expect(allNotifRes.status()).toBe(200);
      const allNotif = await allNotifRes.json();
      expect(allNotif.unreadCount).toBeGreaterThanOrEqual(3);
      const types = new Set(allNotif.notifications.map((n: { type: string }) => n.type));
      expect(types.has('comment')).toBe(true);
      expect(types.has('like')).toBe(true);
      expect(types.has('follow')).toBe(true);

      // 验证按分类筛选准确返回对应类型
      for (const filterType of ['comment', 'like', 'follow'] as const) {
        const filteredRes = await page.request.get(`/api/notifications?type=${filterType}`);
        expect(filteredRes.status()).toBe(200);
        const filtered = await filteredRes.json();
        expect(filtered.notifications.length).toBeGreaterThanOrEqual(1);
        expect(
          filtered.notifications.every((n: { type: string }) => n.type === filterType),
          `type=${filterType} 筛选结果不得混入其他类型`
        ).toBe(true);
      }

      // 汇总未读计数校验
      const unreadSummary = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(unreadSummary.notificationsUnread).toBe(allNotif.unreadCount);

      // 跨用户安全隔离（IDOR 防护）：用户 C 不可读取且不可标记用户 A 的通知为已读
      const notifC = await (await ctxC.request.get('/api/notifications')).json();
      expect(JSON.stringify(notifC)).not.toContain(bComment);
      const firstNotifIdA = allNotif.notifications[0].id as string;
      await ctxC.request.post('/api/notifications/read', { data: { ids: [firstNotifIdA] } });
      const afterIdorAttempt = await (await page.request.get('/api/notifications')).json();
      const targetStillUnread = afterIdorAttempt.notifications.find(
        (n: { id: string; isRead: boolean }) => n.id === firstNotifIdA
      );
      expect(targetStillUnread?.isRead, '他人越权标记已读不得影响目标用户通知状态').toBe(false);

      // 用户 A 单条标为已读 -> 再一键全部标为已读
      const readOneRes = await page.request.post('/api/notifications/read', {
        data: { ids: [firstNotifIdA] },
      });
      expect(readOneRes.status()).toBe(200);
      const readOneJson = await readOneRes.json();
      expect(readOneJson.unreadCount).toBe(allNotif.unreadCount - 1);

      const readAllRes = await page.request.post('/api/notifications/read', { data: { all: true } });
      expect(readAllRes.status()).toBe(200);
      expect((await readAllRes.json()).unreadCount).toBe(0);

      // 删帖后关联通知应被清理且列表查询正常
      expect((await page.request.delete(`/api/posts/${postId}`)).status()).toBe(200);
      const afterDeleteNotifRes = await page.request.get('/api/notifications');
      expect(afterDeleteNotifRes.status()).toBe(200);
      const afterDeleteNotif = await afterDeleteNotifRes.json();
      expect(
        afterDeleteNotif.notifications.some((n: { post?: { id: string } | null }) => n.post?.id === postId),
        '删除帖子后不应残留指向已删除帖子的通知'
      ).toBe(false);
    } finally {
      await ctxB.close();
      await ctxC.close();
      await anonCtx.close();
    }
  });

  test('3. WebSocket 握手安全边界、通知实时推送与零 HTTP 轮询网络审计', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录请求 /api/ws 必须返回 401
      const anonWsRes = await anonCtx.request.get('/api/ws');
      expect(anonWsRes.status(), '未登录访问 /api/ws 必须返回 401').toBe(401);

      const userA = await loginUser(page.request, makeEmail('ws-notif-a'), '实时接收者A');
      await loginUser(ctxB.request, makeEmail('ws-notif-b'), '实时触发者B');

      // 已登录但未携带 Upgrade: websocket 头应返回 426（或 400）
      const nonUpgradeRes = await page.request.get('/api/ws');
      expect([400, 426]).toContain(nonUpgradeRes.status());

      // 伪造跨站 Origin 尝试握手应被 403（或 426）拒绝
      const crossOriginRes = await page.request.get('/api/ws', {
        headers: { Origin: 'https://evil-attacker.example' },
      });
      expect([403, 426]).toContain(crossOriginRes.status());

      const postRes = await page.request.post('/api/posts', {
        data: { title: `WS推送测试帖-${Date.now()}`, content: '验证无需轮询实时推送' },
      });
      const postId = (await postRes.json()).post.id;

      // 在加载页面前监听浏览器建立的 /api/ws 连接
      const wsPromise = page.waitForEvent('websocket', (ws) => ws.url().includes('/api/ws'));
      await page.goto('/');
      const ws = await wsPromise;
      expect(ws.url()).toContain('/api/ws');

      // 首屏初始化稳定后，开启 7 秒静置期网络审计（超过旧版 5 秒轮询周期），断言零轮询
      await page.waitForTimeout(1500);
      const polledUrls: string[] = [];
      const onRequest = (req: { url: () => string; method: () => string }) => {
        const u = req.url();
        if (
          req.method() === 'GET' &&
          (u.includes('/api/messages/') || u.includes('/api/notifications'))
        ) {
          polledUrls.push(u);
        }
      };
      page.on('request', onRequest);
      await page.waitForTimeout(7000);
      page.off('request', onRequest);
      expect(polledUrls, '静置期间严禁对通知或私信接口发起 HTTP 轮询').toEqual([]);

      // 进入通知页，在不刷新页面的前提下由用户 B 触发新评论与新关注，断言页面实时渲染
      const sidebar = page.locator('aside').first();
      const notifNav = sidebar
        .getByRole('button', { name: /通知/ })
        .or(sidebar.getByRole('link', { name: /通知/ }))
        .first();
      await notifNav.click();

      const liveComment = `WS实时评论推送-${Date.now()}`;
      expect((await ctxB.request.post(`/api/users/${userA.id}/follow`)).status()).toBe(200);
      expect(
        (await ctxB.request.post(`/api/posts/${postId}/comments`, { data: { content: liveComment } })).status()
      ).toBe(201);

      // 严禁 reload：直接断言新通知通过 WebSocket 实时呈现在页面上
      await expect(page.getByText(liveComment).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText('实时触发者B').first()).toBeVisible({ timeout: 10000 });

      // 点击一键全部标为已读并验证生效
      const markAllBtn = page.getByRole('button', { name: /全部标为已读|全部已读|清空未读/i }).first();
      if (await markAllBtn.isVisible().catch(() => false)) {
        await markAllBtn.click();
        await expect
          .poll(async () => (await (await page.request.get('/api/notifications/unread-count')).json()).notificationsUnread)
          .toBe(0);
      }
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('4. 私信 WebSocket 实时收发、已读接口校验与聊天窗零轮询审计', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('ws-dm-a'), '私信接收方A');
      const userB = await loginUser(ctxB.request, makeEmail('ws-dm-b'), '私信发送方B');

      // 校验新增单会话已读接口边界
      expect((await anonCtx.request.post(`/api/messages/with/${userB.id}/read`)).status()).toBe(401);
      expect((await page.request.post(`/api/messages/with/${userA.id}/read`)).status()).toBe(400);
      expect((await page.request.post('/api/messages/with/non-existent-peer/read')).status()).toBe(404);

      // 先建立一条初始私信，使会话出现在列表中
      const firstMsg = `开场问候-${Date.now()}`;
      expect(
        (await ctxB.request.post(`/api/messages/with/${userA.id}`, { data: { content: firstMsg } })).status()
      ).toBe(201);

      const wsPromise = page.waitForEvent('websocket', (ws) => ws.url().includes('/api/ws'));
      await page.goto('/');
      await wsPromise;

      const sidebar = page.locator('aside').first();
      const dmNav = sidebar
        .getByRole('button', { name: /私信/ })
        .or(sidebar.getByRole('link', { name: /私信/ }))
        .first();
      await dmNav.click();

      const peerItem = page.getByText(userB.nickname).first();
      await expect(peerItem).toBeVisible({ timeout: 10000 });
      await peerItem.click();
      await expect(page.getByText(firstMsg).first()).toBeVisible({ timeout: 10000 });

      // 聊天窗打开稳定后审计 7 秒内零 HTTP 轮询请求
      await page.waitForTimeout(1500);
      const dmPolled: string[] = [];
      const onDmReq = (req: { url: () => string; method: () => string }) => {
        if (req.method() === 'GET' && req.url().includes('/api/messages/')) {
          dmPolled.push(req.url());
        }
      };
      page.on('request', onDmReq);
      await page.waitForTimeout(7000);
      page.off('request', onDmReq);
      expect(dmPolled, '私信聊天窗口静置期间严禁发生 HTTP 轮询').toEqual([]);

      // 用户 B 再次发送一条新私信，用户 A 页面不刷新直接通过 WebSocket 实时收到并渲染
      const liveDm = `WebSocket秒达私信-${Date.now()}`;
      expect(
        (await ctxB.request.post(`/api/messages/with/${userA.id}`, { data: { content: liveDm } })).status()
      ).toBe(201);
      await expect(page.getByText(liveDm).first()).toBeVisible({ timeout: 10000 });
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('5. 动态详情页 Instagram 风格左右双栏几何结构、互动闭环与移动端适配', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await loginUser(page.request, makeEmail('ig-detail'), '视觉摄影师');

    const uploadRes = await page.request.post('/api/uploads', {
      multipart: {
        file: { name: 'ig-photo.png', mimeType: 'image/png', buffer: PNG_32X32 },
      },
    });
    expect(uploadRes.status()).toBe(201);
    const { url: imageUrl } = await uploadRes.json();

    const postTitle = `Instagram双栏美学-${Date.now()}`;
    const postContent = '桌面端左侧沉浸式展示图片，右侧独立滚动正文与评论，底部固定互动输入栏。';
    const createRes = await page.request.post('/api/posts', {
      data: { title: postTitle, content: postContent, imageUrl, tags: ['摄影美学'] },
    });
    expect(createRes.status()).toBe(201);

    await page.goto('/');
    await expect(page.getByText(postTitle).first()).toBeVisible({ timeout: 10000 });
    await page.getByText(postTitle).first().click();

    const dialog = page.getByRole('dialog').first();
    await expect(dialog).toBeVisible({ timeout: 10000 });
    await expect(dialog.getByText(postTitle).first()).toBeVisible();
    await expect(dialog.getByText(postContent).first()).toBeVisible();

    // 几何验证：桌面端详情弹窗为宽幅左右双栏结构（图片在左，评论输入互动区在右）
    const dialogImg = dialog
      .locator(`img[src="${imageUrl}"]`)
      .or(dialog.getByRole('img', { name: postTitle }))
      .first();
    const commentInput = dialog
      .getByPlaceholder(/评论|说点什么|共鸣|留言/i)
      .or(dialog.locator('input[type="text"], input:not([type]), textarea'))
      .first();

    await expect(dialogImg).toBeVisible({ timeout: 10000 });
    await expect(commentInput).toBeVisible({ timeout: 10000 });

    const dialogBox = await dialog.boundingBox();
    const imgBox = await dialogImg.boundingBox();
    const inputBox = await commentInput.boundingBox();
    expect(dialogBox).not.toBeNull();
    expect(imgBox).not.toBeNull();
    expect(inputBox).not.toBeNull();
    if (dialogBox && imgBox && inputBox) {
      expect(dialogBox.width, '桌面端双栏详情弹窗应具备充足宽度(>=700px)').toBeGreaterThanOrEqual(700);
      expect(imgBox.x + imgBox.width, '左侧图片区应严格位于右侧评论互动区左侧').toBeLessThanOrEqual(
        inputBox.x + 24
      );
    }

    // 在右侧互动区发表评论并验证实时上屏
    const detailComment = `双栏弹窗评论体验真棒-${Date.now()}`;
    await commentInput.fill(detailComment);
    const commentPostPromise = page.waitForResponse(
      (res) => res.url().includes('/comments') && res.request().method() === 'POST'
    );
    const sendBtn = dialog.getByRole('button', { name: /发送|发布/i }).first();
    await sendBtn.click();
    expect((await commentPostPromise).status()).toBe(201);
    await expect(dialog.getByText(detailComment).first()).toBeVisible({ timeout: 10000 });

    // 关闭弹窗后切换移动端视口，验证通知底部导航与详情弹窗无溢出适配
    await page.keyboard.press('Escape');
    await expect(dialog).toBeHidden({ timeout: 5000 });

    await page.setViewportSize({ width: 390, height: 844 });
    const mobileNav = page.getByRole('navigation', { name: /移动端导航/i }).or(page.locator('nav').last()).first();
    await expect(mobileNav.getByText(/通知/).first()).toBeVisible({ timeout: 10000 });

    await page.getByText(postTitle).first().click();
    const mobileDialog = page.getByRole('dialog').first();
    await expect(mobileDialog).toBeVisible({ timeout: 10000 });
    const mobileDialogBox = await mobileDialog.boundingBox();
    expect(mobileDialogBox).not.toBeNull();
    if (mobileDialogBox) {
      expect(mobileDialogBox.width, '移动端详情弹窗不得超出屏幕宽度').toBeLessThanOrEqual(390);
    }
  });
});
